from itertools import product

# marker -> 4 different characters
signals = [
    'mjqjpqmgbljsphdztnvjfqwrcgsmlb',    #                                     7   .. message marker after  19
    'bvwbjplbgvbhsrlpgdmjqwftvncz',      # first packet marker after character 5                            23
    'nppdvjthqldpwncqszvftbrmjlhg',      # first packet marker after character 6                            23
    'nznrnfrfntjfmvfwmzdfjlvtqnbhcprsg', # first packet marker after character 10                           29
    'zcfzfwzzqfrljwzlrfnpqdbhtmscgvjw',  # first packet marker after character 11                           26
    ''
]

for signal in signals:
    i = 0
    while i + 4 <= len(signal):
        s, shift = signal[i:i + 4], 0
        # go from back in order to skip as many characters as possible
        for m in range(3, -1, -1):
            for n in range(m - 1, -1, -1):
                if (s[m] == s[n]):
                    shift = n + 1
                    break
            if shift > 0: break
        if shift == 0: break
        i += shift
    print(i + 4)

